    settingHelp:{"notif": "ڕێگە دەدات ئەم مۆبایلە نامەکانی ریکۆ و بیرخەرەوەی دابینکەران پیشان بدات، تەنانەت کاتێک ئەپەکە داخراوە. هەر مۆبایلێک دوگمەی خۆی هەیە.", "swipe": "لە شاشەی داواکاری، کاڵایەک بەلادا ڕابکێشە بۆ زیادکردنی ئەو بڕەی بەزۆری داوای دەکەیت. دووبارە ڕایبکێشە بۆ زیادکردنی جارێکی تر.", "showLastQty": "هەر کاڵایەک لە شاشەی داواکاری پیشان دەدات جاری پێشوو چەندت داوا کردووە، بۆ ئەوەی بە خێرایی وەک ئەو داوای بکەیتەوە.", "compactRows": "دێڕەکانی کاڵا لە شاشەی داواکاری کورتتر دەبن، بۆ ئەوەی کاڵای زیاتر بە یەکجار جێی ببێتەوە.", "soundQty": "هەر جارێک + یان − دادەگریت دەنگێکی نەرم و کورت لێدەدرێت.", "soundSent": "کاتێک داواکاریی هەموو دابینکەران نێردرا، زەنگێکی کورت لێدەدرێت.", "soundRico": "کاتێک وەڵامی ریکۆ دێت، دوو نۆتی نەرم لێدەدرێن.", "soundError": "کاتێک شتێک سەرنەکەوت، وەک PIN ی هەڵە یان پاشەکەوتێک کە نەچوو، دوو نۆتی نزم لێدەدرێن.", "soundMilestone": "کاتێک چێشتخانە دەگاتە ئامانجێکی زنجیرە یان خەڵاتێک دەباتەوە، مۆسیقایەکی کورت لێدەدرێت.", "soundUndo": "کاتێک گەڕاندنەوە دەکەیت زەنگی داواکاری بە پێچەوانە لێدەدرێت، بۆ ئەوەی بزانیت گەڕێندرایەوە.", "darkMode": "شێوەی ڕووناک یان تاریک هەڵبژێرە. خۆکار وەک مۆبایل یان کۆمپیوتەرەکەت دەبێت و شەوان دەگۆڕێت.", "simpleView": "ڕوونکردنەوە بچووکەکان، ئامۆژگاری و ئەو شتانەی کەم پێویستت پێیانە دەشارێتەوە. هەموو شتێک وەک خۆی کار دەکات.", "tables": "کاڵاکان و دابینکەران لە بەڕێوەبردن دەبنە خشتە کە دەتوانیت ڕیزیان بکەیت، پاڵاوتنیان بکەیت و ستوونەکانیان هەڵبژێریت. کوژاوە لیستێکی سادە پیشان دەدات.", "kitchenMode": "نووسینی گەورەتر و دوگمەی گەورەتر لە هەموو شوێنێک، ئاسانتر بۆ خوێندنەوە و داگرتن لەسەر تابلێتی هاوبەشی چێشتخانە.", "milestones": "خەڵاتی بچووک پیشان دەدات، وەک 30 ڕۆژ لە دوای یەک داواکاری، کاتێک چێشتخانە پێیان دەگات.", "ricoAutoStart": "کاتێک ئەپەکە دەکەیتەوە و ریکۆ لەسەر ماک کوژاوەیە، خۆی دەست پێدەکات، بە مەرجێک ماکەکە هەڵکرابێت.", "tfAuto": "ناردنی گواستنەوەیەک بۆ ریکۆ وەک ڕەزامەندیی تۆ هەژمار دەکرێت، بۆیە بێ پرسیارکردنەوە دەیگوازێتەوە. ئەگەر شتێک هەڵە دیار بێت هێشتا دەوەستێت.", "rrStop": "ریکۆ ڕادەگرێت: هیچ پسوولەیەکی نوێ وەرناگرێت تا ئەمە دەکوژێنیتەوە.", "ricoAutoOrder": "کاتێک ریکۆ داواکارییەک پێشنیار دەکات، ڕاستەوخۆ دەچێتە داواکاریی ئەمڕۆ لە جیاتی کارتێک کە دایبگریت. هیچ شتێک نانێردرێت تا ناردن دانەگریت.", "ricoSheet": "دوگمەی پرسیار لە ریکۆ بۆ شاشەی داواکاری زیاد دەکات، بۆ ئەوەی بێ جێهێشتنی دەربارەی داواکارییەکەت بپرسیت.", "ai": "ریکۆ پێویستی بە خزمەتگوزارییەکی زیرەکی دەستکرد هەیە بۆ وەڵامدانەوە. کاتێک هەڵکراوە، نامەکانت دەچن بۆ Claude Haiku، Google Gemini یان Groq. کاتێک کوژاوەیە، ریکۆ سەرەتا دەپرسێت."}, settingHelpBtn:n=>'دەربارەی '+n,
